using Cosmos.Application.Abstractions.Persistence;
using Cosmos.Application.Abstractions.Services;
using Cosmos.Application.PurchaseExpense;
using Cosmos.Contracts.Audit;
using Cosmos.Contracts.Common;
using Cosmos.Contracts.PurchaseExpense;
using Cosmos.Shared.Exceptions;
using Cosmos.Shared.Responses;
using Cosmos.Shared.Security;
using FluentValidation;

namespace Cosmos.Application.Services;

public sealed class PurchaseExpenseService : IPurchaseExpenseService
{
    private readonly IPurchaseExpenseRepository _repo; private readonly IAuditRepository _audit; private readonly ICurrentUser _user;
    private readonly IValidator<CreatePurchaseBillRequest> _bill; private readonly IValidator<CreateSupplierPaymentRequest> _payment; private readonly IValidator<CreateExpenseCategoryRequest> _category; private readonly IValidator<CreateExpenseRequest> _expense; private readonly IValidator<CreatePurchaseOrderRequest> _order; private readonly IValidator<CreatePurchaseReturnRequest> _return; private readonly IValidator<PurchaseBillListQuery> _billList;
    public PurchaseExpenseService(IPurchaseExpenseRepository repo, IAuditRepository audit, ICurrentUser user, IValidator<CreatePurchaseBillRequest> bill, IValidator<CreateSupplierPaymentRequest> payment, IValidator<CreateExpenseCategoryRequest> category, IValidator<CreateExpenseRequest> expense, IValidator<CreatePurchaseOrderRequest> order, IValidator<CreatePurchaseReturnRequest> @return, IValidator<PurchaseBillListQuery> billList) => (_repo,_audit,_user,_bill,_payment,_category,_expense,_order,_return,_billList)=(repo,audit,user,bill,payment,category,expense,order,@return,billList);
    private long? UserId => _user.UserId; private int? AuditUserId => UserId is null ? null : checked((int)UserId.Value);
    private Task Audit(string table,long id,string action,object? before,object? after,CancellationToken ct)=>_audit.AddAsync(new AuditEntryRequest(table,id.ToString(),action,before is null?null:AuditSerializer.Serialize(before),after is null?null:AuditSerializer.Serialize(after),AuditUserId),ct);
    private static T Found<T>(T? value,string name) where T:class => value ?? throw new NotFoundException($"{name} was not found.");

    public async Task<ApiResponse<PagedResult<PurchaseBillDto>>> GetPurchaseBillsAsync(PurchaseBillListQuery q,CancellationToken ct){await ValidationRunner.ValidateAsync(_billList,q,ct);return ApiResponse<PagedResult<PurchaseBillDto>>.Success(await _repo.GetPurchaseBillsAsync(q,ct));}
    public async Task<ApiResponse<PurchaseBillDetailDto>> GetPurchaseBillAsync(long id,CancellationToken ct)=>ApiResponse<PurchaseBillDetailDto>.Success(Found(await _repo.GetPurchaseBillAsync(id,ct),"Purchase bill"));
    public async Task<ApiResponse<PurchaseBillDetailDto>> CreatePurchaseBillAsync(CreatePurchaseBillRequest r,CancellationToken ct){await ValidationRunner.ValidateAsync(_bill,r,ct);var x=await _repo.CreatePurchaseBillAsync(r,UserId,ct);await Audit("PurchaseBills",x.Id,"Create",null,x,ct);return ApiResponse<PurchaseBillDetailDto>.Success(x,"Purchase bill created.");}
    public async Task<ApiResponse<PurchaseBillDetailDto>> UpdatePurchaseBillAsync(long id,UpdatePurchaseBillRequest r,CancellationToken ct){var mapped=new CreatePurchaseBillRequest(r.SupplierId,r.SupplierInvoiceNo,r.BillDate,r.DueDate,r.PaymentType,r.Items,r.DiscountAmount,r.RoundOff,r.PaidAmount,r.Notes);await ValidationRunner.ValidateAsync(_bill,mapped,ct);var old=Found(await _repo.GetPurchaseBillAsync(id,ct),"Purchase bill");var x=await _repo.UpdatePurchaseBillAsync(id,r,UserId,ct);await Audit("PurchaseBills",id,"Update",old,x,ct);return ApiResponse<PurchaseBillDetailDto>.Success(x,"Purchase bill updated.");}
    public Task<ApiResponse<PurchaseBillDetailDto>> ConfirmPurchaseBillAsync(long id,CancellationToken ct)=>BillStatus(id,true,ct); public Task<ApiResponse<PurchaseBillDetailDto>> CancelPurchaseBillAsync(long id,CancellationToken ct)=>BillStatus(id,false,ct);
    private async Task<ApiResponse<PurchaseBillDetailDto>> BillStatus(long id,bool confirm,CancellationToken ct){var old=Found(await _repo.GetPurchaseBillAsync(id,ct),"Purchase bill");var x=await _repo.ChangePurchaseBillStatusAsync(id,confirm,UserId,ct);await Audit("PurchaseBills",id,confirm?"Confirm":"Cancel",old,x,ct);return ApiResponse<PurchaseBillDetailDto>.Success(x,confirm?"Purchase bill confirmed.":"Purchase bill cancelled.");}
    public async Task<ApiResponse> DeletePurchaseBillAsync(long id,CancellationToken ct){var old=Found(await _repo.GetPurchaseBillAsync(id,ct),"Purchase bill");await _repo.DeletePurchaseBillAsync(id,UserId,ct);await Audit("PurchaseBills",id,"Delete",old,null,ct);return ApiResponse.Success("Purchase bill deleted.");}

    public async Task<ApiResponse<PagedResult<SupplierPaymentDto>>> GetSupplierPaymentsAsync(SupplierPaymentListQuery q,CancellationToken ct)=>ApiResponse<PagedResult<SupplierPaymentDto>>.Success(await _repo.GetSupplierPaymentsAsync(q,ct));
    public async Task<ApiResponse<SupplierPaymentDto>> GetSupplierPaymentAsync(long id,CancellationToken ct)=>ApiResponse<SupplierPaymentDto>.Success(Found(await _repo.GetSupplierPaymentAsync(id,ct),"Supplier payment"));
    public async Task<ApiResponse<SupplierPaymentDto>> CreateSupplierPaymentAsync(CreateSupplierPaymentRequest r,CancellationToken ct){await ValidationRunner.ValidateAsync(_payment,r,ct);var x=await _repo.SaveSupplierPaymentAsync(null,r,UserId,ct);await Audit("SupplierPayments",x.Id,"Create",null,x,ct);return ApiResponse<SupplierPaymentDto>.Success(x,"Payment-out created.");}
    public async Task<ApiResponse<SupplierPaymentDto>> UpdateSupplierPaymentAsync(long id,UpdateSupplierPaymentRequest r,CancellationToken ct){var mapped=new CreateSupplierPaymentRequest(r.SupplierId,r.PaymentDate,r.Amount,r.PaymentMode,r.ReferenceNo,r.Notes,r.Allocations);await ValidationRunner.ValidateAsync(_payment,mapped,ct);var old=Found(await _repo.GetSupplierPaymentAsync(id,ct),"Supplier payment");var x=await _repo.SaveSupplierPaymentAsync(id,mapped,UserId,ct);await Audit("SupplierPayments",id,"Update",old,x,ct);return ApiResponse<SupplierPaymentDto>.Success(x,"Payment-out updated.");}
    public async Task<ApiResponse> DeleteSupplierPaymentAsync(long id,CancellationToken ct){var old=Found(await _repo.GetSupplierPaymentAsync(id,ct),"Supplier payment");await _repo.DeleteSupplierPaymentAsync(id,UserId,ct);await Audit("SupplierPayments",id,"Delete",old,null,ct);return ApiResponse.Success("Payment-out deleted.");}

    public async Task<ApiResponse<PagedResult<ExpenseCategoryDto>>> GetExpenseCategoriesAsync(ExpenseCategoryListQuery q,CancellationToken ct)=>ApiResponse<PagedResult<ExpenseCategoryDto>>.Success(await _repo.GetExpenseCategoriesAsync(q,ct)); public async Task<ApiResponse<ExpenseCategoryDto>> GetExpenseCategoryAsync(long id,CancellationToken ct)=>ApiResponse<ExpenseCategoryDto>.Success(Found(await _repo.GetExpenseCategoryAsync(id,ct),"Expense category"));
    public async Task<ApiResponse<ExpenseCategoryDto>> CreateExpenseCategoryAsync(CreateExpenseCategoryRequest r,CancellationToken ct){await ValidationRunner.ValidateAsync(_category,r,ct);var x=await _repo.SaveExpenseCategoryAsync(null,r,UserId,ct);await Audit("ExpenseCategories",x.Id,"Create",null,x,ct);return ApiResponse<ExpenseCategoryDto>.Success(x,"Expense category created.");}
    public async Task<ApiResponse<ExpenseCategoryDto>> UpdateExpenseCategoryAsync(long id,UpdateExpenseCategoryRequest r,CancellationToken ct){var mapped=new CreateExpenseCategoryRequest(r.Name,r.Description,r.IsActive);await ValidationRunner.ValidateAsync(_category,mapped,ct);var old=Found(await _repo.GetExpenseCategoryAsync(id,ct),"Expense category");var x=await _repo.SaveExpenseCategoryAsync(id,mapped,UserId,ct);await Audit("ExpenseCategories",id,"Update",old,x,ct);return ApiResponse<ExpenseCategoryDto>.Success(x,"Expense category updated.");}
    public async Task<ApiResponse> DeleteExpenseCategoryAsync(long id,CancellationToken ct){var old=Found(await _repo.GetExpenseCategoryAsync(id,ct),"Expense category");await _repo.DeleteExpenseCategoryAsync(id,UserId,ct);await Audit("ExpenseCategories",id,"Delete",old,null,ct);return ApiResponse.Success("Expense category deleted.");}

    public async Task<ApiResponse<PagedResult<ExpenseDto>>> GetExpensesAsync(ExpenseListQuery q,CancellationToken ct)=>ApiResponse<PagedResult<ExpenseDto>>.Success(await _repo.GetExpensesAsync(q,ct)); public async Task<ApiResponse<ExpenseDto>> GetExpenseAsync(long id,CancellationToken ct)=>ApiResponse<ExpenseDto>.Success(Found(await _repo.GetExpenseAsync(id,ct),"Expense"));
    public async Task<ApiResponse<ExpenseDto>> CreateExpenseAsync(CreateExpenseRequest r,CancellationToken ct){await ValidationRunner.ValidateAsync(_expense,r,ct);var x=await _repo.SaveExpenseAsync(null,r,UserId,ct);await Audit("Expenses",x.Id,"Create",null,x,ct);return ApiResponse<ExpenseDto>.Success(x,"Expense created.");}
    public async Task<ApiResponse<ExpenseDto>> UpdateExpenseAsync(long id,UpdateExpenseRequest r,CancellationToken ct){var mapped=new CreateExpenseRequest(r.ExpenseDate,r.CategoryId,r.PaidToPartyId,r.Amount,r.TaxAmount,r.PaymentMode,r.ReferenceNo,r.Notes,r.AttachmentPath);await ValidationRunner.ValidateAsync(_expense,mapped,ct);var old=Found(await _repo.GetExpenseAsync(id,ct),"Expense");var x=await _repo.SaveExpenseAsync(id,mapped,UserId,ct);await Audit("Expenses",id,"Update",old,x,ct);return ApiResponse<ExpenseDto>.Success(x,"Expense updated.");}
    public async Task<ApiResponse> DeleteExpenseAsync(long id,CancellationToken ct){var old=Found(await _repo.GetExpenseAsync(id,ct),"Expense");await _repo.DeleteExpenseAsync(id,UserId,ct);await Audit("Expenses",id,"Delete",old,null,ct);return ApiResponse.Success("Expense deleted.");}

    public async Task<ApiResponse<PagedResult<PurchaseOrderDto>>> GetPurchaseOrdersAsync(PurchaseOrderListQuery q,CancellationToken ct)=>ApiResponse<PagedResult<PurchaseOrderDto>>.Success(await _repo.GetPurchaseOrdersAsync(q,ct)); public async Task<ApiResponse<PurchaseOrderDetailDto>> GetPurchaseOrderAsync(long id,CancellationToken ct)=>ApiResponse<PurchaseOrderDetailDto>.Success(Found(await _repo.GetPurchaseOrderAsync(id,ct),"Purchase order"));
    public async Task<ApiResponse<PurchaseOrderDetailDto>> CreatePurchaseOrderAsync(CreatePurchaseOrderRequest r,CancellationToken ct){await ValidationRunner.ValidateAsync(_order,r,ct);var x=await _repo.SavePurchaseOrderAsync(null,r,UserId,ct);await Audit("PurchaseOrders",x.Id,"Create",null,x,ct);return ApiResponse<PurchaseOrderDetailDto>.Success(x,"Purchase order created.");}
    public async Task<ApiResponse<PurchaseOrderDetailDto>> UpdatePurchaseOrderAsync(long id,UpdatePurchaseOrderRequest r,CancellationToken ct){var mapped=new CreatePurchaseOrderRequest(r.SupplierId,r.OrderDate,r.ExpectedDeliveryDate,r.Items,r.DiscountAmount,r.TermsAndConditions,r.Notes);await ValidationRunner.ValidateAsync(_order,mapped,ct);var old=Found(await _repo.GetPurchaseOrderAsync(id,ct),"Purchase order");var x=await _repo.SavePurchaseOrderAsync(id,mapped,UserId,ct);await Audit("PurchaseOrders",id,"Update",old,x,ct);return ApiResponse<PurchaseOrderDetailDto>.Success(x,"Purchase order updated.");}
    public async Task<ApiResponse> DeletePurchaseOrderAsync(long id,CancellationToken ct){var old=Found(await _repo.GetPurchaseOrderAsync(id,ct),"Purchase order");await _repo.DeletePurchaseOrderAsync(id,UserId,ct);await Audit("PurchaseOrders",id,"Delete",old,null,ct);return ApiResponse.Success("Purchase order deleted.");}
    public async Task<ApiResponse<PurchaseOrderDetailDto>> CancelPurchaseOrderAsync(long id,CancellationToken ct){var old=Found(await _repo.GetPurchaseOrderAsync(id,ct),"Purchase order");var x=await _repo.CancelPurchaseOrderAsync(id,UserId,ct);await Audit("PurchaseOrders",id,"Cancel",old,x,ct);return ApiResponse<PurchaseOrderDetailDto>.Success(x,"Purchase order cancelled.");}
    public async Task<ApiResponse<PurchaseBillDetailDto>> ConvertPurchaseOrderAsync(long id,ConvertPurchaseOrderRequest r,CancellationToken ct){var x=await _repo.ConvertPurchaseOrderAsync(id,r,UserId,ct);await Audit("PurchaseOrders",id,"Convert",null,x,ct);return ApiResponse<PurchaseBillDetailDto>.Success(x,"Purchase order converted.");}

    public async Task<ApiResponse<PagedResult<PurchaseReturnDto>>> GetPurchaseReturnsAsync(PurchaseReturnListQuery q,CancellationToken ct)=>ApiResponse<PagedResult<PurchaseReturnDto>>.Success(await _repo.GetPurchaseReturnsAsync(q,ct)); public async Task<ApiResponse<PurchaseReturnDetailDto>> GetPurchaseReturnAsync(long id,CancellationToken ct)=>ApiResponse<PurchaseReturnDetailDto>.Success(Found(await _repo.GetPurchaseReturnAsync(id,ct),"Purchase return"));
    public async Task<ApiResponse<PurchaseReturnDetailDto>> CreatePurchaseReturnAsync(CreatePurchaseReturnRequest r,CancellationToken ct){await ValidationRunner.ValidateAsync(_return,r,ct);var x=await _repo.SavePurchaseReturnAsync(null,r,UserId,ct);await Audit("PurchaseReturns",x.Id,"Create",null,x,ct);return ApiResponse<PurchaseReturnDetailDto>.Success(x,"Purchase return created.");}
    public async Task<ApiResponse<PurchaseReturnDetailDto>> UpdatePurchaseReturnAsync(long id,UpdatePurchaseReturnRequest r,CancellationToken ct){var mapped=new CreatePurchaseReturnRequest(r.PurchaseBillId,r.SupplierId,r.ReturnDate,r.Reason,r.Items,r.Notes);await ValidationRunner.ValidateAsync(_return,mapped,ct);var old=Found(await _repo.GetPurchaseReturnAsync(id,ct),"Purchase return");var x=await _repo.SavePurchaseReturnAsync(id,mapped,UserId,ct);await Audit("PurchaseReturns",id,"Update",old,x,ct);return ApiResponse<PurchaseReturnDetailDto>.Success(x,"Purchase return updated.");}
    public async Task<ApiResponse> DeletePurchaseReturnAsync(long id,CancellationToken ct){var old=Found(await _repo.GetPurchaseReturnAsync(id,ct),"Purchase return");await _repo.DeletePurchaseReturnAsync(id,UserId,ct);await Audit("PurchaseReturns",id,"Delete",old,null,ct);return ApiResponse.Success("Purchase return deleted.");}
    public async Task<ApiResponse<PurchaseSummaryDto>> GetPurchaseSummaryAsync(DateRangeReportQuery q,CancellationToken ct)=>ApiResponse<PurchaseSummaryDto>.Success(await _repo.GetPurchaseSummaryAsync(q,ct)); public async Task<ApiResponse<IReadOnlyCollection<SupplierOutstandingDto>>> GetSupplierOutstandingAsync(CancellationToken ct)=>ApiResponse<IReadOnlyCollection<SupplierOutstandingDto>>.Success(await _repo.GetSupplierOutstandingAsync(ct)); public async Task<ApiResponse<ExpenseSummaryDto>> GetExpenseSummaryAsync(DateRangeReportQuery q,CancellationToken ct)=>ApiResponse<ExpenseSummaryDto>.Success(await _repo.GetExpenseSummaryAsync(q,ct)); public async Task<ApiResponse<IReadOnlyCollection<CategoryWiseExpenseDto>>> GetCategoryWiseExpenseAsync(DateRangeReportQuery q,CancellationToken ct)=>ApiResponse<IReadOnlyCollection<CategoryWiseExpenseDto>>.Success(await _repo.GetCategoryWiseExpenseAsync(q,ct)); public async Task<ApiResponse<IReadOnlyCollection<ItemPurchaseHistoryDto>>> GetItemPurchaseHistoryAsync(long itemId,CancellationToken ct)=>ApiResponse<IReadOnlyCollection<ItemPurchaseHistoryDto>>.Success(await _repo.GetItemPurchaseHistoryAsync(itemId,ct));
